CREATE TABLE document_pdf_parse_attempts (
  id INTEGER PRIMARY KEY,
  document_id INTEGER NOT NULL REFERENCES documents(id),
  source_sha256_hash TEXT CHECK(source_sha256_hash IS NULL OR length(source_sha256_hash)=64),
  parser_id TEXT NOT NULL,
  parser_version TEXT NOT NULL,
  contract_version TEXT NOT NULL,
  outcome TEXT NOT NULL CHECK(outcome IN ('parsed','cached','failed')),
  error_code TEXT,
  result_id INTEGER REFERENCES document_pdf_parse_results(id),
  actor TEXT NOT NULL,
  program TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK((outcome IN ('parsed','cached') AND error_code IS NULL AND result_id IS NOT NULL) OR (outcome='failed' AND error_code IS NOT NULL))
);
CREATE TABLE document_pdf_parse_results (
  id INTEGER PRIMARY KEY,
  document_id INTEGER NOT NULL REFERENCES documents(id),
  source_sha256_hash TEXT NOT NULL CHECK(length(source_sha256_hash)=64),
  parser_id TEXT NOT NULL,
  parser_version TEXT NOT NULL,
  contract_version TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('ok','no_text_layer','malformed_pdf','encrypted_pdf','unsupported_pdf','resource_limit')),
  error_code TEXT,
  page_count INTEGER NOT NULL CHECK(page_count BETWEEN 0 AND 200),
  item_count INTEGER NOT NULL CHECK(item_count BETWEEN 0 AND 200000),
  text_length INTEGER NOT NULL CHECK(text_length BETWEEN 0 AND 5242880),
  result_json TEXT NOT NULL,
  result_sha256_hash TEXT NOT NULL CHECK(length(result_sha256_hash)=64),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(document_id,source_sha256_hash,parser_id,parser_version,contract_version)
);
CREATE TABLE document_pdf_parse_pages (
  id INTEGER PRIMARY KEY,
  result_id INTEGER NOT NULL REFERENCES document_pdf_parse_results(id),
  page_number INTEGER NOT NULL CHECK(page_number BETWEEN 1 AND 200),
  width REAL NOT NULL CHECK(width>0), height REAL NOT NULL CHECK(height>0), rotation INTEGER NOT NULL CHECK(rotation IN (0,90,180,270)),
  text TEXT NOT NULL, layout_json TEXT NOT NULL, item_count INTEGER NOT NULL CHECK(item_count BETWEEN 0 AND 25000),
  page_sha256_hash TEXT NOT NULL CHECK(length(page_sha256_hash)=64),
  UNIQUE(result_id,page_number)
);
CREATE INDEX idx_document_pdf_parse_attempts_document ON document_pdf_parse_attempts(document_id,id DESC);
CREATE INDEX idx_document_pdf_parse_results_document ON document_pdf_parse_results(document_id,id DESC);
CREATE INDEX idx_document_pdf_parse_pages_result ON document_pdf_parse_pages(result_id,page_number);
CREATE TRIGGER document_pdf_parse_attempts_no_update BEFORE UPDATE ON document_pdf_parse_attempts BEGIN SELECT RAISE(ABORT,'document pdf parse attempts are append-only'); END;
CREATE TRIGGER document_pdf_parse_attempts_no_delete BEFORE DELETE ON document_pdf_parse_attempts BEGIN SELECT RAISE(ABORT,'document pdf parse attempts are append-only'); END;
CREATE TRIGGER document_pdf_parse_results_no_update BEFORE UPDATE ON document_pdf_parse_results BEGIN SELECT RAISE(ABORT,'document pdf parse results are append-only'); END;
CREATE TRIGGER document_pdf_parse_results_no_delete BEFORE DELETE ON document_pdf_parse_results BEGIN SELECT RAISE(ABORT,'document pdf parse results are append-only'); END;
CREATE TRIGGER document_pdf_parse_pages_no_update BEFORE UPDATE ON document_pdf_parse_pages BEGIN SELECT RAISE(ABORT,'document pdf parse pages are append-only'); END;
CREATE TRIGGER document_pdf_parse_pages_no_delete BEFORE DELETE ON document_pdf_parse_pages BEGIN SELECT RAISE(ABORT,'document pdf parse pages are append-only'); END;
CREATE VIEW document_pdf_parses AS SELECT id,document_id,source_sha256_hash,parser_id,parser_version,contract_version,status,error_code,page_count,item_count,text_length,result_json,result_sha256_hash,created_at FROM document_pdf_parse_results;
